// Des: Tests for M14: SSE, long-poll and WebSocket frames with caps
// Flo: mock feeds > sseRead / wsRead > assert exact frame count, deadline, frame cap, JSONL record
// I/O: mock server + local Chrome for WebSocket (skipped when absent) > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const rigz = @import("te-brow-rig.zig"); const strm = @import("nt-strm-read.zig"); const pipe = @import("ru-page-fetc.zig"); const cdp = @import("nt-brow-cdpz.zig");
const allo = std.testing.allocator;
fn url(rig: *rigz.Rig, buf: []u8, path: []const u8) []const u8 { return rig.srv.urlOf(buf, path); }
test "SSE: exactly the 5 events, in order" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf: [64]u8 = undefined; const got = try strm.sseRead(allo, aren.allocator(), std.testing.io, url(&rig, &buf, "/sse"), .{ .priv = true, .time_mill = 5000 }); try std.testing.expectEqual(@as(usize, 5), got.len); try std.testing.expectEqualStrings("msg1", got[0]); try std.testing.expectEqualStrings("msg5", got[4]); }
test "frame cap stops an endless feed fast" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf: [64]u8 = undefined; const t0 = cdp.nowMs(std.testing.io); const got = try strm.sseRead(allo, aren.allocator(), std.testing.io, url(&rig, &buf, "/sseinf"), .{ .priv = true, .time_mill = 20000, .framz = 7 }); try std.testing.expectEqual(@as(usize, 7), got.len); try std.testing.expect(cdp.nowMs(std.testing.io) - t0 < 5000); }
test "deadline stops an endless feed" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf: [64]u8 = undefined; const t0 = cdp.nowMs(std.testing.io); const got = try strm.sseRead(allo, aren.allocator(), std.testing.io, url(&rig, &buf, "/sseinf"), .{ .priv = true, .time_mill = 400 }); try std.testing.expect(got.len >= 1 and got.len < 100); try std.testing.expect(cdp.nowMs(std.testing.io) - t0 < 4000); }
test "NDJSON lines are frames, JSONL keeps them valid" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf: [64]u8 = undefined; const got = try strm.sseRead(allo, aren.allocator(), std.testing.io, url(&rig, &buf, "/ndjson"), .{ .priv = true, .time_mill = 5000 }); try std.testing.expectEqual(@as(usize, 2), got.len); const out = try strm.jsonl(aren.allocator(), got); try std.testing.expectEqualStrings("{\"a\":1}\n{\"a\":2}\n", out); const txt = try strm.jsonl(aren.allocator(), &.{"plain text"}); try std.testing.expectEqualStrings("\"plain text\"\n", txt); }
test "long-poll: repeated GETs until the frame cap" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf: [64]u8 = undefined; const got = try strm.sseRead(allo, aren.allocator(), std.testing.io, url(&rig, &buf, "/poll"), .{ .priv = true, .time_mill = 8000, .framz = 3, .repeat = true }); try std.testing.expectEqual(@as(usize, 3), got.len); try std.testing.expect(!std.mem.eql(u8, got[0], got[2])); }
test "bad status is a typed error; private host refused without the test flag" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf: [64]u8 = undefined; try std.testing.expectError(error.BadStatus, strm.sseRead(allo, aren.allocator(), std.testing.io, url(&rig, &buf, "/e403"), .{ .priv = true, .time_mill = 3000 })); const none = try strm.sseRead(allo, aren.allocator(), std.testing.io, url(&rig, &buf, "/sse"), .{ .priv = false, .time_mill = 2000 }); try std.testing.expectEqual(@as(usize, 0), none.len); }
test "stream record is saved as kind strm, once" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf: [64]u8 = undefined; const urlz = url(&rig, &buf, "/sse"); const got = try strm.sseRead(allo, aren.allocator(), std.testing.io, urlz, .{ .priv = true, .time_mill = 5000 }); const body = try strm.jsonl(aren.allocator(), got); const out = try pipe.pageSave(aren.allocator(), std.testing.io, rig.lad.conf, &rig.dbzz, rig.dirz, urlz, null, .{ .code = 200, .ctyp = "application/x-ndjson", .body = body }); try std.testing.expectEqualStrings("new", out.stat); try std.testing.expectEqualStrings("strm", out.kind); const rec = (try rig.reco("/sse")).?; try std.testing.expectEqualStrings("\"msg1\"\n\"msg2\"\n\"msg3\"\n\"msg4\"\n\"msg5\"\n", rec.body); }
test "WebSocket via Chrome: exact frame count, then a cap and a deadline" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); try rig.skipNo(); var aren = std.heap.ArenaAllocator.init(allo); defer aren.deinit(); var buf: [64]u8 = undefined; const got = try strm.wsRead(&rig.rnd, aren.allocator(), url(&rig, &buf, "/wspage"), .{ .time_mill = 8000 }); try std.testing.expectEqual(@as(usize, 5), got.len); try std.testing.expectEqualStrings("tick 1", got[0]); try std.testing.expectEqualStrings("tick 5", got[4]); var buf2: [64]u8 = undefined; const cap = try strm.wsRead(&rig.rnd, aren.allocator(), url(&rig, &buf2, "/wspage?inf"), .{ .time_mill = 8000, .framz = 3 }); try std.testing.expectEqual(@as(usize, 3), cap.len); var buf3: [64]u8 = undefined; const t0 = cdp.nowMs(std.testing.io); const dl = try strm.wsRead(&rig.rnd, aren.allocator(), url(&rig, &buf3, "/wspage?inf"), .{ .time_mill = 1500 }); try std.testing.expect(dl.len >= 1 and dl.len < 100); try std.testing.expect(cdp.nowMs(std.testing.io) - t0 < 4000); }
